"""The security state is generated by the engine from the files the core declares, checked against what the core gave, and placed in every profile by copy.

The engine's generate mode does not exist in a binary yet: `_fake_security_state_engine.py` is a stand-in that respects the contract exactly (it refuses a command line, a work profile
or a `user.js` that is not the contract's), so a green run of the ok path is also the proof that the core writes exactly what the contract says. No browser, no network. No test
measures a time: an age is given as data (`now`), and the one timeout is the argument of the call.
"""
from __future__ import annotations

import hashlib
import json
import os
import subprocess
import sys
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path

import psutil
import pytest

from invisible_core import _security_state_generate as gen
from invisible_core.constants import (
    CRLITE_MAX_AGE_S,
    CRLITE_PREF,
    INTERMEDIATES_PREF,
    ONECRL_PREF,
    SECURITY_STATE_DIR_NAME,
    SECURITY_STATE_GENERATE_PREF,
    SECURITY_STATE_RESULT_NAME,
)

FAKE = Path(__file__).with_name("_fake_security_state_engine.py")
ENGINE = gen.EngineId(version="159.0", build_id="20261119174916")
#: Only a bound for a test that would otherwise wait for ever (the fake never writing its pids); it decides nothing when the fake works.
SAFETY_POLLS = 1200
STAMPS = {"intermediates": 1763000001, "onecrl": 1763000002, "cert-revocations": 1763000003}


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _inputs(root: Path) -> gen.Inputs:
    """Small valid inputs: an intermediates list, a OneCRL file and a CRLite manifest with a full filter and two deltas beside it."""
    root.mkdir(parents=True, exist_ok=True)
    files = {"full.filter": b"FULL-FILTER-BYTES" * 10, "1.delta": b"delta-one", "2.delta": b"delta-two-longer"}
    for name, data in files.items():
        (root / name).write_bytes(data)
    (root / "intermediates.json").write_text(json.dumps({"format": 1, "collection": "security-state/intermediates",
                                                         "collection_timestamp": STAMPS["intermediates"], "certs": []}))
    (root / "onecrl.json").write_text(json.dumps({"format": 1, "collection": "onecrl", "collection_timestamp": STAMPS["onecrl"],
                                                  "updated_utc": "2026-11-19T10:00:00Z", "revocations": []}))

    def entry(name):
        return {"file": name, "sha256": _sha(files[name]), "size": len(files[name])}

    (root / "crlite.json").write_text(json.dumps({
        "format": 1, "collection": "cert-revocations", "channel": "default", "collection_timestamp": STAMPS["cert-revocations"],
        "updated_utc": "2026-11-19T10:00:00Z", "full": entry("full.filter"), "deltas": [entry("1.delta"), entry("2.delta")]}))
    return gen.Inputs(root / "intermediates.json", root / "onecrl.json", root / "crlite.json")


@pytest.fixture
def run(tmp_path, monkeypatch):
    """`run(mode, **kw)`: a generation with the fake in `mode`; the inputs, the output and the work root are attributes of it."""
    inputs = _inputs(tmp_path / "inputs")
    work_root = tmp_path / "work"
    work_root.mkdir()
    out_dir = tmp_path / "out"

    def go(mode: str = "ok", argv=None, **kw):
        monkeypatch.setenv("FAKE_ENGINE_MODE", mode)
        monkeypatch.setenv("FAKE_ENGINE_VERSION", ENGINE.version)
        monkeypatch.setenv("FAKE_ENGINE_BUILD_ID", ENGINE.build_id)
        kw.setdefault("work_root", work_root)
        return gen.generate([sys.executable, "-I", str(FAKE)] + ["-headless", "-no-remote"] if argv is None else argv, inputs, ENGINE, out_dir, **kw)

    go.inputs, go.out_dir, go.work_root = inputs, out_dir, work_root
    return go


def _is_alive(pid: int) -> bool:
    try:
        return psutil.Process(pid).status() != psutil.STATUS_ZOMBIE
    except psutil.NoSuchProcess:
        return False


