@pytest.mark.integration
def test_a_generation_leaves_the_directory_and_the_report_in_the_output(run):
    result = run()
    assert result["ok"] is True and result["engine"]["build_id"] == ENGINE.build_id
    state = run.out_dir / SECURITY_STATE_DIR_NAME
    assert sorted(p.name for p in state.iterdir()) == ["1.delta", "2.delta", "crlite.filter", "data.safe.bin"]
    assert (state / "crlite.filter").read_bytes() == (run.inputs.crlite.parent / "full.filter").read_bytes()
    assert json.loads((run.out_dir / SECURITY_STATE_RESULT_NAME).read_text()) == result
    assert list(run.work_root.iterdir()) == [], "the work profile is deleted"


@pytest.mark.unit
def test_the_work_profile_is_what_the_contract_says(tmp_path):
    inputs = _inputs(tmp_path / "inputs")
    profile = tmp_path / "profile"
    profile.mkdir()
    gen._write_user_js(profile, inputs)
    assert [p.name for p in profile.iterdir()] == ["user.js"]
    raw = (profile / "user.js").read_bytes()
    assert b"\r" not in raw and raw.endswith(b"\n")
    lines = raw.decode().split("\n")[:-1]
    assert lines == [
        'user_pref("%s", true);' % SECURITY_STATE_GENERATE_PREF,
        'user_pref("%s", %s);' % (INTERMEDIATES_PREF, json.dumps(str(inputs.intermediates.resolve()))),
        'user_pref("%s", %s);' % (ONECRL_PREF, json.dumps(str(inputs.onecrl.resolve()))),
        'user_pref("%s", %s);' % (CRLITE_PREF, json.dumps(str(inputs.crlite.resolve()))),
    ]


