@pytest.mark.integration
def test_an_engine_that_hangs_is_ended_with_its_whole_tree(run, tmp_path, monkeypatch):
    pidfile = tmp_path / "hang.pids"
    monkeypatch.setenv("FAKE_ENGINE_PIDFILE", str(pidfile))

    def the_timeout_comes_once_the_tree_exists(proc, timeout_s):
        # No clock decides when the timeout "happens": it is declared once the fake and its child are known to exist (the fake writes both pids, child first started).
        for _ in range(SAFETY_POLLS):
            if pidfile.is_file() and len(pidfile.read_text().split()) == 2:
                break
            time.sleep(0.05)
        return None

    monkeypatch.setattr(gen, "_wait_for_exit", the_timeout_comes_once_the_tree_exists)
    with pytest.raises(gen.GenerationError, match="did not finish"):
        run("hang")
    engine_pid, child_pid = (int(x) for x in pidfile.read_text().split())
    assert not _is_alive(engine_pid) and not _is_alive(child_pid)
    assert psutil.Process().children(recursive=True) == [], "nothing of the tree is left under this process"
    assert not run.out_dir.exists() and list(run.work_root.iterdir()) == []


class _Proc:
    def __init__(self, raises=None, code=0):
        self.raises, self.code = raises, code

    def wait(self, timeout=None):
        if self.raises:
            raise self.raises
        return self.code


@pytest.mark.unit
def test_the_wait_for_the_engine_says_none_on_a_timeout_and_the_code_otherwise():
    assert gen._wait_for_exit(_Proc(raises=subprocess.TimeoutExpired("engine", 1)), 1) is None
    assert gen._wait_for_exit(_Proc(code=0), 1) == 0
    assert gen._wait_for_exit(_Proc(code=3), 1) == 3


