def _good(inputs: gen.Inputs) -> dict:
    exp = inputs.expected()
    return {"format": 1, "ok": True, "error": None, "engine": {"version": ENGINE.version, "build_id": ENGINE.build_id},
            "collections": {"intermediates": {"collection_timestamp": exp.timestamps["intermediates"]},
                            "onecrl": {"collection_timestamp": exp.timestamps["onecrl"]},
                            "cert-revocations": {"collection_timestamp": exp.timestamps["cert-revocations"], "channel": "default"}},
            "crlite_filter_hashes": sorted(exp.crlite_hashes)}


@pytest.mark.unit
def test_the_expected_values_are_the_ones_the_files_declare(tmp_path):
    exp = _inputs(tmp_path).expected()
    assert exp.timestamps == STAMPS
    assert exp.crlite_hashes == {_sha(b"FULL-FILTER-BYTES" * 10), _sha(b"delta-one"), _sha(b"delta-two-longer")}


@pytest.mark.unit
def test_a_report_that_is_exactly_what_was_given_is_accepted(tmp_path):
    inputs = _inputs(tmp_path)
    gen.validate_result(_good(inputs), inputs, ENGINE)
    gen.validate_result(_good(inputs), inputs, gen.EngineId(version=None, build_id=ENGINE.build_id))


MUTATIONS = [
    ("format", lambda r: r.update(format=2), "format"),
    ("format true", lambda r: r.update(format=True), "format"),
    ("not ok", lambda r: r.update(ok=False, error="boom"), "ok is"),
    ("build id", lambda r: r["engine"].update(build_id="1"), "build_id"),
    ("version", lambda r: r["engine"].update(version="158.0"), "version"),
    ("intermediates stamp", lambda r: r["collections"]["intermediates"].update(collection_timestamp=1), "intermediates"),
    ("onecrl stamp", lambda r: r["collections"]["onecrl"].update(collection_timestamp=1), "onecrl"),
    ("crlite stamp", lambda r: r["collections"]["cert-revocations"].update(collection_timestamp=1), "cert-revocations"),
    ("no collection", lambda r: r["collections"].pop("onecrl"), "onecrl"),
    ("channel", lambda r: r["collections"]["cert-revocations"].update(channel="other"), "channel"),
    ("a hash missing", lambda r: r["crlite_filter_hashes"].pop(), "missing"),
    ("an extra hash", lambda r: r["crlite_filter_hashes"].append("0" * 64), "unexpected"),
    ("upper case hash", lambda r: r["crlite_filter_hashes"].__setitem__(0, r["crlite_filter_hashes"][0].upper()), "lowercase"),
    ("hashes not a list", lambda r: r.update(crlite_filter_hashes="abc"), "list"),
]


@pytest.mark.unit
@pytest.mark.parametrize("label, mutate, says", [pytest.param(*m, id=m[0]) for m in MUTATIONS])
def test_a_report_that_differs_in_one_thing_is_refused(tmp_path, label, mutate, says):
    inputs = _inputs(tmp_path)
    result = _good(inputs)
    mutate(result)
    with pytest.raises(gen.GenerationError, match=says):
        gen.validate_result(result, inputs, ENGINE)


@pytest.mark.unit
def test_a_report_that_is_not_an_object_is_refused(tmp_path):
    with pytest.raises(gen.GenerationError):
        gen.validate_result([], _inputs(tmp_path), ENGINE)


